const getFundById = `-- name: GetFundById :one
WITH FundStats AS (SELECT fund_id,
                          COALESCE(SUM(amount_cents - refunded_cents), 0)::INTEGER AS total_donated,
                          COUNT(*)                                AS total_donations,
                          CASE
                              WHEN COUNT(*) > 0 THEN COALESCE(SUM(amount_cents - refunded_cents), 0) / COUNT(*)
                              ELSE 0
                              END                                 AS average_donation,
                          COUNT(DISTINCT donor_id)                AS total_donors
                   FROM donation
                            JOIN member m ON donation.donor_id = m.id
                            LEFT JOIN donation_payment dp ON donation.id = dp.donation_id
                   GROUP BY fund_id)
SELECT f.id, f.name, f.description, f.provider_id, f.provider_name, f.goal_cents, f.payout_frequency, f.active, f.principal, f.expires, f.next_payment, f.created, f.updated, f.enrollees_visible,
       fs.total_donated,
       fs.total_donations,
       fs.average_donation,
       fs.total_donors
FROM fund f
         LEFT JOIN FundStats fs ON f.id = fs.fund_id
WHERE f.id = $1
`

type GetFundByIdRow struct {
	ID               uuid.UUID
	Name             string
	Description      string
	ProviderID       string
	ProviderName     string
	GoalCents        pgtype.Int4
	PayoutFrequency  PayoutFrequency
	Active           bool
	Principal        uuid.NullUUID
	Expires          NullDBTime
	NextPayment      DBTime
	Created          pgtype.Timestamptz
	Updated          pgtype.Timestamptz
	EnrolleesVisible bool
	TotalDonated     pgtype.Int4
	TotalDonations   pgtype.Int8
	AverageDonation  pgtype.Int4
	TotalDonors      pgtype.Int8
}

func (q *Queries) GetFundById(ctx context.Context, id uuid.UUID) (GetFundByIdRow, error) {
	row := q.db.QueryRow(ctx, getFundById, id)
	var i GetFundByIdRow
	err := row.Scan(
		&i.ID,
		&i.Name,
		&i.Description,
		&i.ProviderID,
		&i.ProviderName,
		&i.GoalCents,
		&i.PayoutFrequency,
		&i.Active,
		&i.Principal,
		&i.Expires,
		&i.NextPayment,
		&i.Created,
		&i.Updated,
		&i.EnrolleesVisible,
		&i.TotalDonated,
		&i.TotalDonations,
		&i.AverageDonation,
		&i.TotalDonors,
	)
	return i, err
}

