const upsertFundImage = `-- name: UpsertFundImage :one
INSERT INTO fund_image (fund_id, s3_key, content_type, width, height, sha256)
VALUES ($1, $2, $3, $4, $5, $6)
ON CONFLICT (fund_id)
    DO UPDATE SET s3_key       = excluded.s3_key,
                  content_type = excluded.content_type,
                  width        = excluded.width,
                  height       = excluded.height,
                  sha256       = excluded.sha256,
                  updated      = now()
RETURNING fund_id, s3_key, content_type, width, height, sha256, created, updated
`

type UpsertFundImageParams struct {
	FundID      uuid.UUID
	S3Key       string
	ContentType string
	Width       int32
	Height      int32
	Sha256      string
}

// One image per fund, so uploading a second replaces the first.
func (q *Queries) UpsertFundImage(ctx context.Context, arg UpsertFundImageParams) (FundImage, error) {
	row := q.db.QueryRow(ctx, upsertFundImage,
		arg.FundID,
		arg.S3Key,
		arg.ContentType,
		arg.Width,
		arg.Height,
		arg.Sha256,
	)
	var i FundImage
	err := row.Scan(
		&i.FundID,
		&i.S3Key,
		&i.ContentType,
		&i.Width,
		&i.Height,
		&i.Sha256,
		&i.Created,
		&i.Updated,
	)
	return i, err
}

const upsertFundNote = `-- name: UpsertFundNote :one
INSERT INTO fund_note (id, fund_id, member_id, body, anonymous)
VALUES ($1, $2, $3, $4, $5)
ON CONFLICT (fund_id, member_id)
    DO UPDATE SET body      = excluded.body,
                  anonymous = excluded.anonymous,
                  updated   = now(),
                  -- Whose decision it was decides whether writing again undoes it.
                  --
                  -- A moderator's stands: editing must not be a way to put back
                  -- something that was taken down, and it must not be a way to find
                  -- out that it was.
                  --
                  -- The author's own does not. Taking your note down and later
                  -- writing another is an ordinary thing to do, and this preserved
                  -- the removal for everybody -- so a donor who once used their own
                  -- remove button was locked out of that fund for good, told each
                  -- time that their note was up while nothing appeared.
                  --
                  -- removed_by is NULL when the note is live, and NULL = member_id
                  -- is NULL, so an unremoved note takes the ELSE and keeps its NULLs.
                  removed_at = CASE
                                   WHEN fund_note.removed_by = fund_note.member_id THEN NULL
                                   ELSE fund_note.removed_at END,
                  removed_by = CASE
                                   WHEN fund_note.removed_by = fund_note.member_id THEN NULL
                                   ELSE fund_note.removed_by END
RETURNING id, fund_id, member_id, body, anonymous, removed_at, removed_by, created, updated
`

type UpsertFundNoteParams struct {
	ID        uuid.UUID
	FundID    uuid.UUID
	MemberID  uuid.UUID
	Body      string
	Anonymous bool
}

// One note per donor per fund, so writing one twice edits it.
func (q *Queries) UpsertFundNote(ctx context.Context, arg UpsertFundNoteParams) (FundNote, error) {
	row := q.db.QueryRow(ctx, upsertFundNote,
		arg.ID,
		arg.FundID,
		arg.MemberID,
		arg.Body,
		arg.Anonymous,
	)
	var i FundNote
	err := row.Scan(
		&i.ID,
		&i.FundID,
		&i.MemberID,
		&i.Body,
		&i.Anonymous,
		&i.RemovedAt,
		&i.RemovedBy,
		&i.Created,
		&i.Updated,
	)
	return i, err
}
